    {
      "fieldName": "ucinn_ascendv2__View_Critical_Information_Button_Display__c",
      "toolTip": "Determines when to display the View Critical Information button.",
      "customFieldParams": {
        "type": "picklist",
        "label": "View Critical Information Button Display",
        "customPicklistValuesString": [
          "Always Show",
          "Always Hide",
          "Hide If No Critical Information"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Knowtify_Button_Label__c",
