      }
    },
    {
      "fieldName": "ucinn_ascendv2__Aggregate_Household__c",
      "toolTip": "Show all the household member comments and data records, along with the household comments and data records at the same time.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Aggregate Household"
      }
