  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Default_Tab__c",
      "toolTip": "Determines which tab (Bio Demo, Gift Processing, Interim, Review Transaction (v2)) is active when Knowtify modal is opened. If blank, use the enabled tab field (Enable Bio Demo Tab, Enable Gift Processing Tab, Enable Interim Tab, Enable Review Transaction (v2) Tab) based on the specified context.",
      "customFieldParams": {
        "type": "picklist",
        "label": "Default Tab",
        "customPicklistValuesString": [
          "Bio Demo",
          "Gift Processing",
          "Interim",
          "Review Transaction"
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Appearance__c",
      "toolTip": "Sets the default appearance for how Knowtify is presented.\n\nManual: Manually invoke modal\nDisruptive: Always shows at the opening of a page\nPop-Up: Small notification to optionally open modal\n\nIf blank, use the appearance specified for the context (Bio Demo Appearance, Gift Processing Appearance, Interim Appearance, Review Transaction (v2) Appearance)",
      "customFieldParams": {
        "type": "picklist",
        "label": "Appearance",
        "customPicklistValuesString": [
          "Manual",
          "Disruptive",
          "Pop-Up"
        ]
